def compute(vars):
    commercial_fair_value = vars["v1"]
    total_loans_held_for_sale = vars["v2"]

    if total_loans_held_for_sale == 0:
        return None

    ratio = commercial_fair_value / total_loans_held_for_sale
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "commercial_fair_value": commercial_fair_value,
            "total_loans_held_for_sale": total_loans_held_for_sale,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
